app.controller('settingController', ['$scope', '$routeParams', '$rootScope', '$http', 'ajaxService', '$location', 'NgTableParams', 'Upload', '$timeout',
    function ($scope, $routeParams, $rootScope, $http, ajaxService, $location, NgTableParams, Upload, $timeout) {
        "use strict";
        var self = this;

        self.prompts = {
            p1: 'شما یک استخراج‌کننده و تحلیل‌گر رزومه هستید. ورودی: متن کامل رزومه که از یک PDF استخراج شده است. وظایف شما: ### 1) استخراج ساختار رزومه در قالب JSON زیر: Skills: - {{Title: ...}} Experiences: - {{Project: ...}} - {{Company: ...}} - {{Role: ...}} - {{Activity: ...}} - {{Benefit: ...}} Educations: - {{Academy: ...}} - {{Degree: ...}} Certificates: - {{Academy: ...}} - {{Title: ...}} - {{Skill: ...}} ### 2) زبان هر متن را مطابق رزومه حفظ کنید (انگلیسی/فارسی) ### 3) یک فیلد JobTitle تولید کنید که عنوان شغلی ۳–۴ کلمه‌ای انگلیسی باشد. ### 4) آنالیز 10 بُعد کیفی رزومه (Resume Analysis) خروجی باید شامل آرایه‌ای با 10 آبجکت باشد. هر آیتم شامل: - Dimension - Score (0–10) - Comments ابعاد پیشنهادی: 1. Clarity 2. Structure 3. Experience Relevance 4. Technical Skill Strength 5. Communication Quality 6. Achievement Quantification 7. Seniority Level Fit 8. Language Quality 9. Completeness 10. Overall Professionalism ### 5) Summary در 3–4 جمله، خلاصه‌ای از کیفیت کلی رزومه و پیشنهادهای بهبود بدهید. ### 6) خروجی نهایی فقط و فقط JSON باشد با قالب زیر: {{ ""Skills"": [], ""Experiences"": [], ""Educations"": [], ""Certificates"": [], ""JobTitle"": ""..."", ""ResumeAnalysis"": [ {{""Dimension"": ""..."", ""Score"": 0, ""Comments"": ""...""}} ], ""Summary"": ""..."" }} متن رزومه: {{" + resumeText + "}}',
            p2: 'You are a professional assistant specialized in writing respectful and formal responses to employers. Task: - You will receive the text of a message or email sent by an employer to a job applicant. - Analyze the tone and content of the employer’s message. - Based on the content, generate a polite and professional response that helps the applicant reply appropriately. Guidelines: 1. If the employer expresses interest or asks for further steps (like interviews, tests, documents, or scheduling calls), write a positive, cooperative reply confirming availability and appreciation. 2. If the employer rejects the application or says no position is available, write a respectful thank-you note that keeps the connection open for future opportunities. 3. If the employer asks for clarification or more information (e.g., portfolio, salary expectations, documents), write a clear, concise, and polite message providing what was requested. 4. The response must sound natural, professional, and courteous — avoid over-formality or robotic tone. 5. The message should be written in the same language as the employer’s message (detect automatically). 6. The generated reply must follow ONLY these rules and nothing else. Additional classification task: You MUST classify the employer’s message into EXACTLY one of the following types: - Rejected → Employer declines or no position available. - Passed → Employer expresses interest or positivity but does NOT request an interview. - Interview → Employer requests or suggests a meeting, call, or interview. The type field MUST NOT be empty. If the message is ambiguous, choose the closest match. Output format requirement: You MUST return ONLY a single JSON object with EXACTLY these two fields: { ""text"": ""<the generated reply>"", ""type"": ""<Rejected | Passed | Interview>"" } - Absolutely no explanation. - No commentary. - No additional text outside the JSON. - The text value must contain ONLY the applicants response.Example input: “The company appreciates your interest, but currently we do not have a suitable position available.” Example output: { ""text"": ""Thank you very much for considering my application.I truly appreciate your time and the opportunity.I hope we can stay in touch for future openings that match my background."", ""type"": ""Rejected"" } Now analyze the following employer message and produce ONLY the JSON:',
            p3: 'You are a professional cover letter writer and career communication expert. You must respond in English only. Input Data: - Applicant: FullName: ""{EscapeForJson(User.FirstName + " " + User.LastName)}"" Address: ""{EscapeForJson(User.Address)}"" Email: ""{EscapeForJson(User.Email)}"" Phone: ""{EscapeForJson(User.PhoneNumber)}"" - Resume (compact): Skills: ""{EscapeForJson(skills)}"" Experiences: ""{EscapeForJson(experiences)}"" Educations: ""{EscapeForJson(educations)}"" Certificates: ""{EscapeForJson(certificates)}"" - Jobs: an array of job objects (Indexed). Use the jobs list below exactly as given. [ {jobsBlock} ] Task: For each job object above produce a tailored, professional, ATS-friendly cover letter in English. Return the result as a JSON array. Each array element must be an object with the exact fields: - Title (string) - Company (string) - Location (string) - Link (string) - JobType (int) - CoverLetter (string) Strict output rules: - Return ONLY valid JSON; no explanations, no extra text, no markdown fences. - The JSON must be an array with one object per input job (preserve Index ordering). - Use the exact job Title and Company values in the cover letter where appropriate. - Address each letter to ""Dear Manager"". - Do NOT include applicant address or date in header. - Keep tone professional, confident, and concise. Each CoverLetter should be ~180-350 words tailored to the job. - If any input field is empty, still return the field with empty string. - Do not translate or localize names or terms. Now produce the JSON array.',
            p4: 'You are an information extractor. Input: an English transcript where the user verbally talks about their skills, projects, company, role, activities, benefits, educational background, certifications, or professional training. Your task is to extract all relevant information and return a structured JSON result with the following sections: 1) Skills: Extract all mentioned skills. Return as an array of objects: - Title: the skill name exactly as it appears in English. 2) Experiences: Extract project-related and experiences information. Return as an array of objects: - Project: project name (or empty string) - Company: company name (or empty string) - Role: role or position (or empty string) - Activity: main activity or task (or empty string) - Benefit: benefit, goal, or outcome (or empty string) 3) Educations: Extract educational background. Return as an array of objects: - Academy: institution name (or empty string) - Degree: degree or education level (or empty string) 4) Certificates: Extract certifications or professional training. Return as an array of objects: - Academy: issuing organization (or empty string) - Title: certification title (or empty string) - Skill: related skill or expertise area (or empty string) Strict Output Rules: - Output must be valid JSON only. - Output must be entirely in English. - Do not use Persian (Farsi), Arabic, or any non-English words. - Do not translate, interpret, or localize names or terms. - Keep all extracted values exactly as they appear in the input. - If a value is missing, return an empty string """". - If no items exist in an array section, return an empty array []. - Ignore any non-English words in the transcript. Return the result in this exact structure: {{ ""Skills"": {{ ""Title"": """" }}, ""Experiences"": {{ ""Project"": """", ""Company"": """", ""Role"": """", ""Activity"": """", ""Benefit"": """" }}, ""Educations"": {{ ""Academy"": """", ""Degree"": """", ""Score"": 0 }}, ""Certificates"": {{ ""Academy"": """", ""Title"": """", ""Skill"": """", }} }} Now process the following text and return only JSON:',
        };

        self.payment = {
            pay1: '1',
            pay2: '2',
            pay3: '1.5',
        };

        self.initializeController = function () {
            ajaxService.WhoseMenu();
        };

        self.addOrUpdate = function () {
            const model = {
                Id: $rootScope.Skill.Id ? $rootScope.Skill.Id : emptyGuid,
                Title: $rootScope.Skill.Title,
                //Value: $rootScope.Skill.Value,
            }
            return ajaxService.ajaxPost($rootScope.domain + "/api/Skill/AddOrUpdate", model).then(function (data) {
                if (data.status != 200)
                    return;
                location.reload();
            });
        }
    }]);
